typedef struct{uint64_t h[8],bytes;unsigned char b[128];size_t used;int is384;}zov_h64;
static inline uint64_t z64r(uint64_t x,unsigned n){return(x>>n)|(x<<(64-n));}
static inline uint64_t z64get(const unsigned char*p){uint64_t x=0;for(int i=0;i<8;i++)x=(x<<8)|p[i];return x;}
static inline void z64transform(zov_h64*c,const unsigned char*p){static const uint64_t k[80]={0x428a2f98d728ae22ULL,0x7137449123ef65cdULL,0xb5c0fbcfec4d3b2fULL,0xe9b5dba58189dbbcULL,0x3956c25bf348b538ULL,0x59f111f1b605d019ULL,0x923f82a4af194f9bULL,0xab1c5ed5da6d8118ULL,0xd807aa98a3030242ULL,0x12835b0145706fbeULL,0x243185be4ee4b28cULL,0x550c7dc3d5ffb4e2ULL,0x72be5d74f27b896fULL,0x80deb1fe3b1696b1ULL,0x9bdc06a725c71235ULL,0xc19bf174cf692694ULL,0xe49b69c19ef14ad2ULL,0xefbe4786384f25e3ULL,0x0fc19dc68b8cd5b5ULL,0x240ca1cc77ac9c65ULL,0x2de92c6f592b0275ULL,0x4a7484aa6ea6e483ULL,0x5cb0a9dcbd41fbd4ULL,0x76f988da831153b5ULL,0x983e5152ee66dfabULL,0xa831c66d2db43210ULL,0xb00327c898fb213fULL,0xbf597fc7beef0ee4ULL,0xc6e00bf33da88fc2ULL,0xd5a79147930aa725ULL,0x06ca6351e003826fULL,0x142929670a0e6e70ULL,0x27b70a8546d22ffcULL,0x2e1b21385c26c926ULL,0x4d2c6dfc5ac42aedULL,0x53380d139d95b3dfULL,0x650a73548baf63deULL,0x766a0abb3c77b2a8ULL,0x81c2c92e47edaee6ULL,0x92722c851482353bULL,0xa2bfe8a14cf10364ULL,0xa81a664bbc423001ULL,0xc24b8b70d0f89791ULL,0xc76c51a30654be30ULL,0xd192e819d6ef5218ULL,0xd69906245565a910ULL,0xf40e35855771202aULL,0x106aa07032bbd1b8ULL,0x19a4c116b8d2d0c8ULL,0x1e376c085141ab53ULL,0x2748774cdf8eeb99ULL,0x34b0bcb5e19b48a8ULL,0x391c0cb3c5c95a63ULL,0x4ed8aa4ae3418acbULL,0x5b9cca4f7763e373ULL,0x682e6ff3d6b2b8a3ULL,0x748f82ee5defb2fcULL,0x78a5636f43172f60ULL,0x84c87814a1f0ab72ULL,0x8cc702081a6439ecULL,0x90befffa23631e28ULL,0xa4506cebde82bde9ULL,0xbef9a3f7b2c67915ULL,0xc67178f2e372532bULL,0xca273eceea26619cULL,0xd186b8c721c0c207ULL,0xeada7dd6cde0eb1eULL,0xf57d4f7fee6ed178ULL,0x06f067aa72176fbaULL,0x0a637dc5a2c898a6ULL,0x113f9804bef90daeULL,0x1b710b35131c471bULL,0x28db77f523047d84ULL,0x32caab7b40c72493ULL,0x3c9ebe0a15c9bebcULL,0x431d67c49c100d4cULL,0x4cc5d4becb3e42b6ULL,0x597f299cfc657e2aULL,0x5fcb6fab3ad6faecULL,0x6c44198c4a475817ULL};uint64_t w[80];for(int i=0;i<16;i++)w[i]=z64get(p+i*8);for(int i=16;i<80;i++){uint64_t x=w[i-15],y=w[i-2],s0=z64r(x,1)^z64r(x,8)^(x>>7),s1=z64r(y,19)^z64r(y,61)^(y>>6);w[i]=w[i-16]+s0+w[i-7]+s1;}uint64_t a=c->h[0],b=c->h[1],cc=c->h[2],d=c->h[3],e=c->h[4],f=c->h[5],g=c->h[6],h=c->h[7];for(int i=0;i<80;i++){uint64_t s1=z64r(e,14)^z64r(e,18)^z64r(e,41),ch=(e&f)^(~e&g),t1=h+s1+ch+k[i]+w[i],s0=z64r(a,28)^z64r(a,34)^z64r(a,39),maj=(a&b)^(a&cc)^(b&cc),t2=s0+maj;h=g;g=f;f=e;e=d+t1;d=cc;cc=b;b=a;a=t1+t2;}c->h[0]+=a;c->h[1]+=b;c->h[2]+=cc;c->h[3]+=d;c->h[4]+=e;c->h[5]+=f;c->h[6]+=g;c->h[7]+=h;}
static inline void z64init(zov_h64*c,int is384){static const uint64_t i512[8]={0x6a09e667f3bcc908ULL,0xbb67ae8584caa73bULL,0x3c6ef372fe94f82bULL,0xa54ff53a5f1d36f1ULL,0x510e527fade682d1ULL,0x9b05688c2b3e6c1fULL,0x1f83d9abfb41bd6bULL,0x5be0cd19137e2179ULL};static const uint64_t i384[8]={0xcbbb9d5dc1059ed8ULL,0x629a292a367cd507ULL,0x9159015a3070dd17ULL,0x152fecd8f70e5939ULL,0x67332667ffc00b31ULL,0x8eb44a8768581511ULL,0xdb0c2e0d64f98fa7ULL,0x47b5481dbefa4fa4ULL};memset(c,0,sizeof(*c));c->is384=is384;memcpy(c->h,is384?i384:i512,sizeof(c->h));}
static inline void z64update(zov_h64*c,const unsigned char*p,size_t n){c->bytes+=n;while(n){size_t z=128-c->used;if(z>n)z=n;memcpy(c->b+c->used,p,z);c->used+=z;p+=z;n-=z;if(c->used==128){z64transform(c,c->b);c->used=0;}}}
static inline size_t z64final(zov_h64*c,unsigned char*out){uint64_t bits=c->bytes*8;c->b[c->used++]=0x80;if(c->used>112){memset(c->b+c->used,0,128-c->used);z64transform(c,c->b);c->used=0;}memset(c->b+c->used,0,120-c->used);memset(c->b+112,0,8);for(int i=0;i<8;i++)c->b[127-i]=(unsigned char)(bits>>(8*i));z64transform(c,c->b);size_t len=c->is384?48:64;for(size_t i=0;i<len/8;i++){uint64_t x=c->h[i];for(int j=7;j>=0;j--){out[i*8+j]=(unsigned char)x;x>>=8;}}return len;}
#include "hash_check_backend.h"
static inline int zov_hash64_digest_file(const char *name,int alg,unsigned char *out,size_t *outlen){
 FILE *f=stdin;if(strcmp(name,"-")){f=fopen(name,"rb");if(!f)return -1;}
 zov_h64 c;z64init(&c,alg);unsigned char buf[16384];size_t n;
 while((n=fread(buf,1,sizeof buf,f)))z64update(&c,buf,n);
 if(ferror(f)){int e=errno?errno:EIO;if(f!=stdin)fclose(f);errno=e;return -1;}
 if(f!=stdin)fclose(f);*outlen=z64final(&c,out);return 0;
}
static inline const char *zov_hash64_label(const char *program){return !strcmp(program,"sha384sum")?"SHA384":"SHA512";}
static inline int zov_hash64_run(const char*program,int is384,int argc,char**argv){
 for(int i=0;i<argc;i++)if(!strcmp(argv[i],"-c")||!strcmp(argv[i],"--check"))return zov_checksum_check_run(program,zov_hash64_label(program),is384, is384?48:64,argc,argv,zov_hash64_digest_file);
 char**files=(char**)malloc((size_t)(argc+1)*sizeof(char*));if(!files)return 1;int nf=0,status=0,tag=0,zero=0;for(int i=0;i<argc;i++){if(!strcmp(argv[i],"--binary")||!strcmp(argv[i],"-b")||!strcmp(argv[i],"--text")||!strcmp(argv[i],"-t"))continue;if(!strcmp(argv[i],"--tag")){tag=1;continue;}if(!strcmp(argv[i],"--zero")||!strcmp(argv[i],"-z")){zero=1;continue;}if(!strcmp(argv[i],"--version")){printf("%s (zovutils) 0.10.38\n",program);free(files);return 0;}if(!strcmp(argv[i],"--help")){printf("Usage: %s [OPTION]... [FILE]...\nPrint or check %s checksums.\nWith no FILE, or when FILE is -, read standard input.\n  --help     display this help and exit\n  --version  output version information and exit\n",program,program);free(files);return 0;}if(argv[i][0]=='-'&&strcmp(argv[i],"-")){fprintf(stderr,"%s: unrecognized option '%s'\nTry '%s --help' for more information.\n",program,argv[i],program);free(files);return 1;}files[nf++]=argv[i];}int implicit=!nf;if(implicit)files[nf++]="-";for(int fi=0;fi<nf;fi++){const char*name=files[fi];FILE*f=stdin;if(strcmp(name,"-")){f=fopen(name,"rb");if(!f){fprintf(stderr,"%s: %s: %s\n",program,name,strerror(errno));status=1;continue;}}zov_h64 c;z64init(&c,is384);unsigned char buf[16384],dig[64];size_t n;while((n=fread(buf,1,sizeof(buf),f)))z64update(&c,buf,n);if(ferror(f)){fprintf(stderr,"%s: %s: read error: %s\n",program,name,strerror(errno));status=1;}if(f!=stdin)fclose(f);size_t len=z64final(&c,dig);zov_checksum_print(program,zov_hash64_label(program),dig,len,implicit?"-":name,tag,zero);}free(files);return status;}
#endif
